import{_ as t}from"./chunks/image34.Dh8mAVwC.js";import{_ as o}from"./chunks/image35.DB3Pfc49.js";import{_ as a}from"./chunks/image40.bIdiuhOZ.js";import{_ as n}from"./chunks/2.BRgDBKom.js";import{_ as r,o as i,c as s,am as l}from"./chunks/framework.CenUaW7a.js";const c="/projects/AiMechaM1/en/advanced-kit/assets/5.C2cWmycM.webp",d="/projects/AiMechaM1/en/advanced-kit/assets/image39.BFIDgqf5.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image41.Ba6K7eYT.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image42.BapyqlAa.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image43.CnYD8qhQ.png",j=JSON.parse('{"title":"3.5 Lesson 5: Diagonal Trajectory Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.5 Lesson 5 Diagonal Trajectory Control.md","filePath":"docs/3. Course materials/3.5 Lesson 5 Diagonal Trajectory Control.md"}'),g={name:"docs/3. Course materials/3.5 Lesson 5 Diagonal Trajectory Control.md"};function u(f,e,y,w,v,_){return i(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="_3-5-lesson-5-diagonal-trajectory-control" tabindex="-1">3.5 Lesson 5: Diagonal Trajectory Control <a class="header-anchor" href="#_3-5-lesson-5-diagonal-trajectory-control" aria-label="Permalink to &quot;3.5 Lesson 5: Diagonal Trajectory Control&quot;">​</a></h1><h2 id="_3-5-1-lesson-introduction" tabindex="-1">3.5.1 Lesson Introduction <a class="header-anchor" href="#_3-5-1-lesson-introduction" aria-label="Permalink to &quot;3.5.1 Lesson Introduction&quot;">​</a></h2><p>Building upon the previous lesson, this lesson expands into diagonal motion and angular control. Taking inspiration from vector concepts and playground slides, the vector decomposition method is introduced to explain diagonal motion as the synthesis of lateral and longitudinal movements. Following the path of &quot;vector principles → four-direction diagonal movement → arbitrary angle control&quot;, this lesson uses force analysis to explain how diagonal wheels generate diagonal resultant forces. Through hands-on practice in four standard diagonal directions, the control method advances to arbitrary angle control ranging from -180° to 180°. Mastering eight-directional motion and angular trajectory control lays a vector thinking foundation for drifting rotation and path planning.</p><h2 id="_3-5-2-learning-objectives" tabindex="-1">3.5.2 Learning Objectives <a class="header-anchor" href="#_3-5-2-learning-objectives" aria-label="Permalink to &quot;3.5.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the physical concept of vector decomposition. Master the analytical method of decomposing diagonal motion into lateral and longitudinal force components. Learn the structural principle of inclined rollers on Mecanum wheels generating diagonal driving forces.</p><p><strong>2.</strong> Implement diagonal movement in four diagonal directions through single-wheel rotational speed control. Master the usage of encapsulated eight-directional movement commands. Proficiently apply angle parameters to control the car moving along any angular direction.</p><p><strong>3.</strong> Establish a physical thinking framework for vector decomposition and synthesis. Cultivate the analytical ability to break down complex motions into simple component motions. Strengthen logical awareness of angular quantification and parameterized control.</p><p><strong>4.</strong> Connect diagonal motion to operation scenarios in narrow spaces. Understand the application value of omnidirectional movement technology in smart manufacturing and agricultural automation. Stimulate interest in exploring motion control and robot navigation technologies.</p><h2 id="_3-5-3-preparation" tabindex="-1">3.5.3 Preparation <a class="header-anchor" href="#_3-5-3-preparation" aria-label="Permalink to &quot;3.5.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation:</strong></p><ul><li><p>AiMecha M1 Mecanum-wheel robot base × 1</p></li><li><p>Type-C USB data cable × 1</p></li><li><p>Computer running Windows or macOS × 1</p></li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running normally</li></ul><p><strong>Angular Coordinate System Description</strong>: A polar coordinate system is adopted to define movement directions, ranging from -180° to 180°. Specifically, 0° represents straight ahead, 90° represents straight right, -90° represents straight left, and both 180° and -180° represent straight backward. Furthermore, 45° corresponds to front-right, -45° corresponds to front-left, 135° corresponds to rear-right, and -135° corresponds to rear-left.</p><p><strong>Device Connection Description</strong>: Connect the mecha controller to the computer using a Type-C data cable. The four motors are pre-wired at the factory, requiring no additional wiring. Testing with a standard angle such as 45° is recommended when using the angular movement command for the first time to verify whether the movement direction matches expectations.</p><h2 id="_3-5-4-hands-on-project" tabindex="-1">3.5.4 Hands-On Project <a class="header-anchor" href="#_3-5-4-hands-on-project" aria-label="Permalink to &quot;3.5.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>This project focuses on the diagonal fixed-point movement of the Mecanum-wheel car, adopting a three-layer logic of &quot;vector decomposition → wheel speed ratio → timing control&quot;. The vector decomposition layer splits diagonal motion into longitudinal and lateral components and calculates their ratio. The wheel speed ratio layer adjusts the rotational speeds and directions of the four Mecanum wheels to synthesize a driving force at a specified angle. The timing control layer relies on wait commands to regulate movement duration and limit displacement. Based on the diagonal wheel driving principle and rotational speed ratio adjustments, any movement direction from -180° to 180° can be synthesized to achieve precise trajectory control of the car.</p><img loading="lazy" height="540" width="960" src="'+c+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="202" width="527" src="'+d+'" class="common_img" style="width:460px;aspect-ratio:527 / 202;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Single-wheel control</td><td style="text-align:center;"><img loading="lazy" height="200" width="511" src="'+t+'" class="common_img" style="width:400px;aspect-ratio:511 / 200;"></td><td style="text-align:left;">Independently sets the rotational speed and direction of each wheel to achieve various diagonal motions through speed ratios.</td></tr><tr><td style="text-align:center;">Eight-direction movement</td><td style="text-align:center;"><img loading="lazy" height="321" width="551" src="'+o+'" class="common_img" style="width:400px;aspect-ratio:551 / 321;"></td><td style="text-align:left;">Encapsulated command supporting eight standard directions, including forward, backward, left, right, and four diagonal directions.</td></tr><tr><td style="text-align:center;">Angular movement</td><td style="text-align:center;"><img loading="lazy" height="64" width="522" src="'+a+'" class="common_img" style="width:400px;aspect-ratio:522 / 64;"></td><td style="text-align:left;">Advanced encapsulated command that controls movement in any direction using angle parameters from -180° to 180°.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Single-Wheel Control for Four-Direction Diagonal Movement</strong></p><ul><li><p>Use the <code>When the A key is pressed briefly</code> block as the program trigger entry.</p></li><li><p>Front-left movement: Set the front-left wheel to 0 rpm + the front-right wheel to 60 rpm + the rear-left wheel to 60 rpm + the rear-right wheel to 0 rpm, so that forward rotation of the right diagonal wheels generates a front-left 45° resultant force.</p></li><li><p>Wait 1 s to maintain the front-left movement state.</p></li><li><p>Front-right movement: Set the front-left wheel to 60 rpm + the front-right wheel to 0 rpm + the rear-left wheel to 0 rpm + the rear-right wheel to 60 rpm, so that forward rotation of the left diagonal wheels generates a front-right 45° resultant force.</p></li><li><p>Wait 1 s to maintain the front-right movement state.</p></li><li><p>Rear-left movement: Set the front-left wheel to -60 rpm + the front-right wheel to 0 rpm + the rear-left wheel to 0 rpm + the rear-right wheel to -60 rpm, so that backward rotation of the left diagonal wheels generates a rear-left 45° resultant force.</p></li><li><p>Wait 1 s to maintain the rear-left movement state.</p></li><li><p>Rear-right movement: Set the front-left wheel to 0 rpm + the front-right wheel to -60 rpm + the rear-left wheel to -60 rpm + the rear-right wheel to 0 rpm, so that backward rotation of the right diagonal wheels generates a rear-right 45° resultant force.</p></li><li><p>Wait 1 s and then execute the stop command.</p></li></ul><img loading="lazy" height="615" width="505" src="'+h+'" class="common_img" style="width:600px;aspect-ratio:505 / 615;"><p><strong>Task 2: Eight-Direction Encapsulated Commands to Simplify Diagonal Movement</strong></p><ul><li><p>Use the encapsulated command <code>set Mecanum-wheel car to move toward a direction at a speed of X rpm</code>.</p></li><li><p>Select the four diagonal directions, front-left, front-right, rear-left, and rear-right, directly from the direction drop-down menu.</p></li><li><p>Set the car to move in each of the four diagonal directions sequentially for 1 s each, and finally stop.</p></li><li><p>Program features: No need to memorize complex wheel speed ratios, making the code concise and intuitive while significantly reducing error rates.</p></li></ul><img loading="lazy" height="521" width="635" src="'+p+'" class="common_img" style="width:400px;aspect-ratio:635 / 521;"><p><strong>Task 3: Angular Control for 45° Diagonal Fixed-Point Movement</strong></p><ul><li>Program entry: Triggered when the A key is pressed briefly.</li><li>Use the <code>Set mecanum to move facing 45 degrees at 60 RPM</code>.</li><li>Add a wait command to control the movement duration, precisely controlling the diagonal movement distance by adjusting the wait time in seconds.</li><li>Execute the <code> Stop mecanum wheels</code> command after the movement ends.</li><li>Extended practice: Modify the angle to different values such as -45°, 135°, and -135° to observe changes in movement direction.</li><li>Key parameters: The angle ranges from -180° to 180°, where higher angular precision yields more accurate movement direction control.</li></ul><img loading="lazy" height="197" width="527" src="'+m+'" class="common_img" style="width:400px;aspect-ratio:527 / 197;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Diagonal Trajectory Control</a>.</strong></p></div><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-5-5-expansion-and-advancement" tabindex="-1">3.5.5 Expansion and Advancement <a class="header-anchor" href="#_3-5-5-expansion-and-advancement" aria-label="Permalink to &quot;3.5.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Diamond Trajectory Cruising</strong></p><p>Write a program using a combination of movements in four diagonal directions to make the car follow a diamond trajectory. Ensure the car moves sequentially along the four 45° diagonal directions, front-right, rear-right, rear-left, and front-left, for an identical duration each, eventually returning near the starting point to form a closed diamond. Precisely control the duration of each movement segment to be consistent, practicing comprehensive skills in angular direction control and trajectory arrangement.</p><p><strong>Project 2: Arbitrary Angle Aiming Movement</strong></p><p>Set a target point in the test field, measure the angle of the line connecting the starting point to the target point, and write a program to make the car move in a straight line along the calculated angle to observe whether it accurately reaches the target position. Set multiple target points at different angles for further challenges to understand the correspondence between angle parameters and actual movement directions, cultivating the ability to combine spatial geometry with engineering practice.</p><h2 id="_3-5-6-q-a" tabindex="-1">3.5.6 Q&amp;A <a class="header-anchor" href="#_3-5-6-q-a" aria-label="Permalink to &quot;3.5.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What is the vector decomposition method?</strong></p><p><strong>Answer</strong>: The vector decomposition method is a fundamental approach in physics for analyzing complex motions and forces. It refers to breaking down a vector with both magnitude and direction into two or more component vectors along mutually perpendicular directions according to the parallelogram law, studying the variation patterns of each component vector individually, and then synthesizing them to obtain the overall effect.</p><p><strong>Q2: During front-left movement, why do only the front-right and rear-left wheels rotate while the front-left and rear-right wheels remain stationary? Does driving with only two wheels cause imbalance?</strong></p><p><strong>Answer</strong>: This is precisely the ingenious design of Mecanum wheels. Driving with two diagonal wheels produces a pure 45° diagonal motion without causing any imbalance.</p><h2 id="_3-5-7-technical-support-and-discussion" tabindex="-1">3.5.7 Technical Support and Discussion <a class="header-anchor" href="#_3-5-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.5.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',49)])])}const P=r(g,[["render",u]]);export{j as __pageData,P as default};
